package com.asmj.marketplace.job.repository; import com.asmj.marketplace.job.model.JobInterview; import org.springframework.data.mongodb.repository.MongoRepository; import java.util.*; public interface JobInterviewRepository extends MongoRepository<JobInterview,String>{List<JobInterview> findByCandidateIdOrderByScheduledAtDesc(String candidateId); List<JobInterview> findByVendorIdOrderByScheduledAtDesc(String vendorId); Optional<JobInterview> findByApplicationId(String applicationId);}
